INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (93, 'page', 'About Us', 'about-us', 1, '<p>Four Rivers Nuclear Partnership, LLC. (FRNP), comprising three strong DOE contractors—Amentum, BWXT, and Fluor—was formed to meet the unique challenges of the Paducah Gaseous Diffusion Plant (PGDP) Deactivation and Remediation (D&amp;R) project. Led by Amentum, FRNP brings new leadership while leveraging lessons learned, site history, and detailed knowledge to deliver cost-effective technical solutions.</p>
