INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (98, 'page', 'Doing Business with Us', 'about/doing-business', 1, '<p>Four Rivers Nuclear Partnership (FRNP) is committed to offering a fair and equitable opportunity for small, small disadvantaged, women-owned small, service-disabled veteran-owned small, and HUBZone small businesses to complete the Paducah deactivation and environmental remediation project.</p>
