INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (103, 'page', 'Community Commitment', 'community-commitment', 1, '<p>FOUR RIVERS NUCLEAR PARTNERSHIP, LLC (FRNP) will partner with community leaders to invest corporate dollars in such a way that it improves educational outreach programs, regional purchasing, and community support. Our presence in the community will be supportive and impactful as we continue to build on the relationships already established.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (120, 'article', 'DOE Science Bowl T-Shirts Will Feature Students Winning Design', 'news/doe-science-bowl-t-shirts-will-feature-students-winning-design', 1, '<p>Calloway County Middle School Science Bowl team coach Scott Pile and visual arts teacher Heather Duffy pose with Jayne Bishop, winner of the 2018 West Kentucky Science Bowl T-Shirt Design Contest. An eighth-grade student, Bishop received the $500 prize for her school for her design of the 2018 official T-shirt to be given to all participating students and coaches at the Feb. 2 middle school and Feb. 16 high school Science Bowl regionals at the University of Kentucky College of Engineering – Paducah Campus.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (121, 'article', 'New Cleanup Contractor Begins at Paducah Site', 'news/new-cleanup-contractor-begins-paducah-site', 1, '<p>Four Rivers Nuclear Partnership, LLC (FRNP), a CH2M-led company with partners Fluor Corporation and BWX Technologies, Inc., commenced work under a new Paducah Deactivation and Remediation (D&amp;R) Contract at EM’s former Paducah Gaseous Diffusion Plant on Oct. 20.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (122, 'article', 'Four Rivers Nuclear Partnership, LLC awarded Department of Energy Paducah Deactivation and Remediation Contract', 'news/four-rivers-nuclear-partnership-llc-awarded-department-energy-paducah-deactivation-and', 1, '<p>The United States Department of Energy announced May 25, 2017 that Four Rivers Nuclear Partnership, LLC. (FRNP), a CH2M-led company with partners Fluor Corporation and BWX Technologies, Inc., was awarded the Paducah Deactivation and Remediation (D&amp;R) Contract at the Paducah Gaseous Diffusion Plant (PGDP). CH2M brings experiences from the Gaseous Diffusion Complexes at East Tennessee Technology Park and all teaming members bring experience from the Portsmouth Site. Fluor will bring continuity of operations to the Paducah D&amp;R Contract as the current contractor.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (157, 'article', 'Paducah Site Workers Educate Girls About STEM Careers', 'news/paducah-site-workers-educate-girls-about-stem-careers', 1, '<p>More than 120 students recently took part in an interactive learning space hosted by&nbsp;EM’s&nbsp;<a href="https://www.energy.gov/pppo">Portsmouth/Paducah Project Office&nbsp;(PPPO)</a> deactivation and remediation contractor at this year’s “STEM 4 Girls” event in Paducah.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (158, 'article', 'Paducah Site Launches Advanced Rescue Training for Firefighters', 'news/paducah-site-launches-advanced-rescue-training-firefighters', 1, '<p>The fire services team at&nbsp;EM’s&nbsp;<a href="https://www.energy.gov/pppo/paducah-site">Paducah Site</a>&nbsp;recently conducted vehicle extrication training courses at the site.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (181, 'article', 'DOE Paducah Site Seeks College Interns for the Summer', 'news/doe-paducah-site-seeks-college-interns-summer', 1, '<p>Two of the U.S. Department of Energy’s (DOE) Paducah Site contractors are accepting applications for their 2019 College Summer Internship Programs.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (204, 'article', 'Paducah Site Installs More-Efficient Alarms', 'news/paducah-site-installs-more-efficient-alarms', 1, '<p>Workers are making changes to reduce utility and maintenance costs for&nbsp;EM’s&nbsp;Paducah Site&nbsp;cleanup.</p>
