INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (282, 'request_for_proposal', 'High Pressure Fire Water (HPFW) Modification', 'procurement/frnp-sd-7488', 1, NULL, 'filtered_html', NULL, '{"department_or_project":"4","description":"<p>Four Rivers Nuclear Partnership, LLC,&nbsp;located in Paducah, Kentucky, is soliciting a contract to perform modifications to 66 Wet-pipe High PressureFire Water systems (HPFW). The goal is to modify the existing Wet-pipe systems to a dry-pipe hybrid type system that is pressurized with air, applying alarm only function (i.e., system dry and manual introduction of water when needed) upon sprinkler activation.</p>\\r\\n\\r\\n<p>See J-24 SOW</p>\\r\\n\\r\\n<p>&nbsp;</p>","rfp_docs":"2164","rfp_number":"FRNP-SD-7488"}', 1, 'draft', NULL, NULL, NULL, '2019-12-23 21:59:26', '2021-02-03 23:19:35') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
