INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (296, 'article', 'Paducah Site Cleanup Workers Achieve One Million Safe Work Hours', 'news/paducah-site-cleanup-workers-achieve-one-million-safe-work-hours', 1, '<p>Deactivation and remediation workers with Four Rivers Nuclear Partnership (FRNP), the prime cleanup contractor at the Paducah Gaseous Diffusion Plant (PGDP), recently surpassed one million work hours without a lost-time accident or illness.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (330, 'page', 'C-400 RI/FS Fieldwork', 'fieldwork', 1, '[filetree dir="sites/default/files/fieldwork"]', 'filtered_html', NULL, '{}', 1, 'published', NULL, NULL, NULL, '2020-05-14 15:59:53', '2020-05-14 15:59:53') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
