INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (425, 'article', 'Paducah Site Clears Area to Investigate the C-400 Complex', 'news/paducah-site-clears-area-investigate-c-400-complex', 1, '<p>Prior to the current COVID-19 restrictions, workers at the U.S. Department of Energy’s (DOE) Paducah Site&nbsp;removed above-ground equipment, pipelines, ventilation stacks, and other infrastructure previously located on the east and west sides of the C-400 Cleaning Building.&nbsp; The work was done to prepare the facility for future demolition as well as to support the planned environmental remedial investigation to be conducted at the C-400 Complex.&nbsp;</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (426, 'article', 'Paducah Site Reduces Waste Inventory', 'news/paducah-site-reduces-waste-inventory', 1, '<p>The U.S. Department of Energy''s (DOE) Paducah Site recently achieved a significant reduction in waste with the offsite shipment of&nbsp;22 "cold traps" formerly used in the uranium-enrichment process. The shipment removed approximately 42 percent of the former gaseous diffusion plant''s enriched uranium inventory.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (427, 'article', 'EM Modifies Paducah Process Building to Maintain Safety and Control Costs', 'news/em-modifies-paducah-process-building-maintain-safety-and-control-costs', 1, '<p>Deactivation workers at&nbsp;EM’s&nbsp;Paducah Site&nbsp;recently completed major modifications to the fire sprinkler system in one of the former gaseous diffusion plant’s four massive uranium-enrichment process buildings.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (428, 'article', 'Paducah Advances Large Building Toward Deactivation', 'news/paducah-advances-large-building-toward-deactivation', 1, '<p>Workers at&nbsp;EM’s&nbsp;Paducah Site&nbsp;recently relocated personnel and operations from 129,800 square feet of space in the C-720 Maintenance and Storage Building to prepare for future deactivation of the large structure.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (429, 'article', 'Paducah Site Transfers Oil to Support Regional Economic Development', 'news/paducah-site-transfers-oil-support-regional-economic-development', 1, '<p>EM’s&nbsp;Paducah Site&nbsp;recently transferred approximately 210,000 gallons of electrical insulating oil to support economic development in the region.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (430, 'article', 'EM Gets Closer Look at Primary Source of Paducah Groundwater Contamination', 'news/em-gets-closer-look-primary-source-paducah-groundwater-contamination', 1, '<p>For the first time, workers at&nbsp;EM’s Paducah Site are able to closely examine the primary source of off-site groundwater contamination directly underneath the C-400 Cleaning Building.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (431, 'article', 'Paducah Material Sizing Area to Drive Deactivation Efficiency, Worker Safety', 'news/paducah-material-sizing-area-drive-deactivation-efficiency-worker-safety', 1, '<p>Workers at&nbsp;EM’s&nbsp;Paducah Site&nbsp;are set to begin constructing a state-of-the-art material sizing area (MSA) in the&nbsp;C-333 Process Building&nbsp;to downsize large components.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (433, 'article', 'FRNP Employees Raise More than $11K for Easter Seals Telethon', 'news/frnp-employees-raise-more-11k-easter-seals-telethon', 1, '<p>Twenty six year old Parker Fralix has attended programs at Easter Seals West Kentucky since graduating from Lone Oak High School in 2013. He is one of many adults benefiting from the social interaction and training programs offered to adults with special needs through Easter Seals.&nbsp;</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (443, 'article', 'Paducah Site Constructing New Scanning Facility for Building Deactivation', 'news/paducah-site-constructing-new-scanning-facility-building-deactivation', 1, '<p>EM’s&nbsp;Paducah Site&nbsp;is constructing a key facility in the cleanup of the former gaseous diffusion plant.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (450, 'page', 'Building On A Legacy', 'building-on-a-legacy', 1, '<link href="misc/video/video-js.css" rel="stylesheet" />
