INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (497, 'article', 'DOE Extends FRNP Contract Three Years', 'news/doe-extends-frnp-contract-three-years', 1, '<p>In June, Four Rivers Nuclear Partnership (FRNP) received the first of two option periods from the U. S. Department of Energy (DOE) &nbsp;to continue &nbsp;deactivation and remediation work through June 19, 2025. The three-year contract is valued at approximately $394 million and will be used to further DOE’s cleanup mission at the Paducah site. &nbsp;</p>
