INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (504, 'article', 'Paducah Tests Its First Robot to Support Cleanup Mission', 'news/paducah-tests-its-first-robot-support-cleanup-mission', 1, '<p>Workers are introducing a first at&nbsp;EM’s&nbsp;Paducah Site&nbsp;— use of robot technology — to set the stage for future deactivation and remediation work at the former Paducah Gaseous Diffusion Plant (PGDP).</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (514, 'article', 'National Safety Council Names FRNP Take Two Team Semi-Finalist for Green Cross Safety Advocate Award', 'news/national-safety-council-names-frnp-take-two-team-semi-finalist-green-cross-safety-advocate', 1, '<p>In August, the National Safety Council (NSC) named Four Rivers Nuclear Partnership’s (FRNP) Take Two for Safety team a semi-finalist for the Green Cross Safety Advocate Award. FRNP is the deactivation and remediation contractor for the U.S. Department of Energy’s (DOE) Paducah site. This prestigious award recognizes a partnership, program, or coalition that has made a significant impact on safety issues at the workplace by advocating for practices that have been proven to raise awareness for the prevention of injuries.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (517, 'article', 'FRNP''s United Way Spirit Week Wrap Up', 'news/frnps-united-way-spirit-week-wrap', 1, '<p>Because of the generosity of our FRNP team, this week’s events raised over $7,500 for the United Way. This is in addition to the funds you donated through the through the Employee Payroll Deduction program this fiscal year. It’s been a fun week and we hope you’ll enjoy this video from yesterday’s Directors’ Pie in the Face event!</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (519, 'article', 'FRNP Awards More Than Half of Procurements to Small Businesses', 'news/frnp-awards-more-half-procurements-small-businesses', 1, '<p>When the deactivation and remediation contractor Four Rivers Nuclear Partnership, LLC (FRNP), won its contract with the U.S. Department of Energy’s (DOE) Paducah site in 2017, DOE established aggressive purchasing goals to help small businesses maximize opportunities with the new contractor. FRNP met or exceeded these goals as reported through the Small Business Administration by the end of its five-year base period, which ended in June. Since the start of FRNP’s contract, approximately 66% of procurements have been awarded to small businesses.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (524, 'article', 'FRNP Celebrates Take Two for Safety Day', 'news/frnp-celebrates-take-two-safety-day', 1, '<p>Employees were invited to FRNP’s Take Two for Safety Day to celebrate our team achieving more than 1.5 million hours of work without a lost workday. Festivities included a lunch, prize drawings, and a host of other events to celebrate FRNP’s excellent safety record.</p>', 'filtered_html', '2021', '{"video":"https://www.youtube.com/embed/wJsH-AhGT1Q","video_photo":"12601"}', 1, 'published', NULL, NULL, NULL, '2022-10-18 21:51:33', '2022-10-21 20:15:48') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (530, 'article', 'Paducah Completes First-of-a-Kind Scanning Facility', 'news/paducah-completes-first-kind-scanning-facility', 1, '<p>Crews have finished building a first-of-a-kind DOE facility that sets the stage to change the way&nbsp;EM’s&nbsp;Paducah Site&nbsp;scans, packages and disposes equipment and waste for the foreseeable future.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (533, 'article', 'FRNP Volunteers Inspire Students to Pursue STEM Careers', 'news/frnp-volunteers-inspire-students-pursue-stem-careers', 1, '<p>Volunteers from Four Rivers Nuclear Partnership teamed up with 35 companies and organizations from across the region to interact with eighth grade students in McCracken County at the West Kentucky Launch. On Wednesday, October 26, over 800 students filled the Expo Center in Paducah to explore future career opportunities in the region during this interactive career exposition.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (541, 'article', 'Three Heath Middle School Students Design Winning T-shirt for DOE Regional Science Bowl', 'news/three-heath-middle-school-students-design-winning-t-shirt-doe-regional-science-bowl', 1, '<p>Three eighth graders from Heath Middle School (HMS) won this year’s U.S. Department of Energy (DOE) West Kentucky Regional Science Bowl t-shirt design contest. Sam Dobson, Caroline Roberts and Gavin Schooley collaborated on a design selected as this year’s official event t-shirt.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (542, 'article', 'Paducah Meets EM-1 Milestone to Remove One Million Pounds of R-114 in CY22', 'news/paducah-meets-em-1-milestone-remove-one-million-pounds-r-114-cy22', 1, '<p>The U.S. Department of Energy’s (DOE) Paducah site recently accomplished an Environmental Management calendar year 2022 priority, successfully dispositioning one million pounds of an ozone-depleting chemical dichlorotetrafluoroethane, commonly known as R-114 refrigerant. Reducing this amount of R-114 refrigerant from the environment has an impact equal to that of reducing greenhouse gas emissions from approximately 10,000 vehicles each year.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (543, 'article', 'DOE Contractors Donate Hundreds of Gifts to Local Children', 'news/doe-contractors-donate-hundreds-gifts-local-children', 1, '<p>Employees at the U.S. Department of Energy’s Paducah site donated hundreds of bicycles, toys and other donations to several local non-profit agencies during the months of November and December. Each year, employees of Four Rivers Nuclear Partnership, LLC (FRNP), Swift &amp; Staley Inc. (SSI), Mid-America Conversion Services, LLC (MCS), and Enterprise Technical Assistance Services, Inc. (ETAS) team up to support several regional non-profit organizations to ensure children receive what they need as well as a few items they want during the holiday season.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (546, 'article', 'Paducah Breaks Ground on New Site Emergency Operations Center', 'news/paducah-breaks-ground-new-site-emergency-operations-center', 1, '<p>As the DOE Paducah site completed its first site-level emergency exercise since the beginning of&nbsp; COVID-19, construction crews broke ground on a new Emergency Operations Center (EOC) to improve the coordination and response to emergencies across the site.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (547, 'page', 'FFA Calendars', 'ffa-calendars', 1, '[filetree dir="sites/default/files/ffa_calendar"]', 'filtered_html', NULL, '{}', 1, 'published', NULL, NULL, NULL, '2023-01-11 20:10:10', '2023-01-11 20:10:10') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (548, 'article', 'Thanks for Being Awesome in 2022', 'news/thanks-being-awesome-2022', 1, '<p>The Four Rivers Nuclear Partnership team has much to be proud of. We have made great progress during the last year and continue to demonstrate a commitment to safety and advancing the mission at the Paducah site. Thanks for being awesome!</p>', 'filtered_html', '2067', '{"video":"https://youtu.be/xtNOfcRFDL8","video_photo":"13407"}', 1, 'published', NULL, NULL, NULL, '2023-01-18 19:59:35', '2023-01-18 20:01:40') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (562, 'article', 'Deactivation of Feed Vaporization Facility Reduced Hazards at DOE Paducah Site', 'news/deactivation-feed-vaporization-facility-reduced-hazards-doe-paducah-site', 1, '<p>Workers have removed materials such as oils, combustibles and environmental hazards from the C-333-A Feed Vaporization Facility at EM’s Paducah Site as part of recent actions to prepare the building and its adjoining process gas building for future demolition.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (563, 'article', 'Winners Advance to Nationals in DOE Science Bowl', 'news/winners-advance-nationals-doe-science-bowl', 1, '<p>Volunteers and coaches have spent months planning for this year’s U.S. Department of Energy (DOE) West Kentucky Regional Science Bowl, an event touted as the region’s most notable science competition for high school and middle&nbsp;school students.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (576, 'page', 'LEAPKY Career Development', 'leap', 1, '<p>LEAP KY is a peer-led organization established by Four Rivers Nuclear Partnership (FRNP) to promote professional development and networking opportunities for FRNP employees. The elements of LEAP KY are Leadership, Engagement, Advancement, and Preparation. LEAP is designed for employees who aspire to transition into management or higher management roles, develop and strengthen their leadership skills, learn about different functions and projects, and network with various levels of FRNP and corporate personnel.<br />
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (578, 'request_for_proposal', 'N2 Tanks Lifting and Landing Services', 'procurement/frnp-pu-0019496', 1, NULL, 'filtered_html', NULL, '{"department_or_project":"2104","description":"<p>FRNP is seeking Subcontractor proposals to perform all rigging, lifting and landing activities of three vertical nitrogen tanks onto three separate trailers.</p>\\r\\n\\r\\n<p>FRNP will be providing an onsite Pre-Bid Meeting on Thursday, April 13, 2023.</p>\\r\\n\\r\\n<p>Proposals will be due Thursday, May 04, 2023.</p>\\r\\n\\r\\n<p>If you are interested in receiving this Request for Proposal please contact Amanda Hatton by email, <a href=\\"mailto:Amanda.Hatton@pad.pppo.gov\\">Amanda.Hatton@pad.pppo.gov</a></p>","rfp_number":"FRNP-PU-0019496"}', 1, 'draft', NULL, NULL, NULL, '2023-04-10 21:51:03', '2023-05-15 23:18:45') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (583, 'page', 'Paducah Site Videos', 'videos', 1, '<link href="https://fourriversnuclearpartnership.com/misc/video/video-js.css" rel="stylesheet" />
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (584, 'article', 'New Equipment Sets Stage for Future Deactivation at Paducah Site', 'news/new-equipment-sets-stage-future-deactivation-paducah-site', 1, '<p>After months of training, field demonstrations and operational drills, workers at&nbsp;EM’s&nbsp;Paducah Site&nbsp;have demonstrated the safe and compliant operation of new equipment to compact components — each roughly the size of a 15-passenger van — as part of upcoming deactivation work for a massive uranium-enrichment process building slated for demolition.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (595, 'article', 'FRNP Challenges Students to ‘Hack’ Plastics Waste Problem', 'news/frnp-challenges-students-‘hack’-plastics-waste-problem', 1, '<p>Students from three regional high schools recently teamed up for Hack the Plastics, an event created by&nbsp;EM’s&nbsp;Paducah Site&nbsp;cleanup contractor to “hack,” or propose solutions, to help solve a part of the global plastics waste problem.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (610, 'article', 'Paducah Builds Toward Ten-Year Goal to Significantly Reduce Site Hazards', 'news/paducah-builds-toward-ten-year-goal-significantly-reduce-site-hazards', 1, '<p>EM&nbsp;workers continue to reduce chemical hazards at the&nbsp;Paducah Site&nbsp;with the recent shipment of 14 sodium fluoride traps, or exchange vessels, for off-site disposal and the elimination of the site’s entire chlorine gas cylinder inventory.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (611, 'request_for_proposal', 'Abandoned Transmission Tower Removal', 'procurement/frnp-pd-20479', 1, NULL, 'filtered_html', NULL, '{"department_or_project":"2131","description":"<p>FRNP is soliciting a contrac to disassemble as many as 86 abandoned electric transmission towers and associated concrete bases located within the DOE Paducah Site reservation. The scope of work is divided into a base option and two other options. The transmission towers within the Padcuah Gasesous Diffusion Plant and the DOE Paducah Site reservation are no longer being used to supply power to the site. FRNP''s goals (driven by DOE expectations) are to recycle as much of the materials as possible. The scrap metals will be provided to the Paducah Area Community Reuse Organization through DOE.&nbsp;</p>","rfp_docs":"15568","rfp_number":"FRNP-PD-20479"}', 1, 'draft', NULL, NULL, NULL, '2023-06-29 16:07:07', '2024-01-18 19:13:03') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (613, 'article', 'EM, Advisory Board Team Up for Paducah’s Groundwater Cleanup Video', 'news/em-advisory-board-team-paducah’s-groundwater-cleanup-video', 1, '<p>The Paducah Site and the Paducah Citizens Advisory Board (CAB) have teamed up to produce a documentary video about EM’s groundwater cleanup program, resulting in a collaborative communication tool that helps audiences understand efforts to remediate off-site groundwater contamination.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (622, 'page', 'Summer Internship Program', 'careers/internship', 1, '<p><iframe frameborder="0" height="432" src="https://www.youtube.com/embed/1Gy8_u7YzeQ" title="YouTube video player" width="768"></iframe></p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (624, 'article', 'Paducah Mutual Aid Agreement Results in Savings to Fire District', 'news/paducah-mutual-aid-agreement-results-savings-fire-district', 1, '<p>The&nbsp;West McCracken Fire District&nbsp;recently praised the&nbsp;DOE Paducah Site’s fire department for the team’s community-minded approach to emergency response.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (625, 'request_for_proposal', 'C-631 Trailer Complex Storm Shelters', 'procurement/frnp-sd-0021502', 1, NULL, 'filtered_html', NULL, '{"amendments":"15953","department_or_project":"5","description":"<p>Four Rivers Nuclear Project is soliciting the fabricate, deliver and install storm shelters for our C-631 trailer complex at the Paducah Gaseous Diffusion Plant.&nbsp; Please review the solicitation very carefully and provide proposals in two volumes, Vol 1-Technical and Vol 2-Cost/Contractual.&nbsp; Reference Section L and M for minimum proposal requirements. The procurement timeline is listed below:</p>\\r\\n\\r\\n<ul style=\\"list-style-type:circle\\">\\r\\n\\t<li>Pre-Bid Conference Call on October 4, 2023 at 11:00 a.m. CST \\u2013 Reference L.4 for call information</li>\\r\\n\\t<li>Submit any questions via email by October 10, 2023</li>\\r\\n\\t<li>Proposal due on or before October 19, 2023 at 2:00 p.m. CST</li>\\r\\n</ul>\\r\\n\\r\\n<p>All associated documents are embedded in the solicitation file.&nbsp;&nbsp;If you have any questions concerning the solicitation please contact me directly.</p>","rfp_docs":"15952","rfp_number":"FRNP-SD-0021502"}', 1, 'draft', NULL, NULL, NULL, '2023-09-26 15:49:48', '2024-01-18 19:13:03') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (627, 'article', 'Facility Demolitions Support Community Reuse at Paducah Site', 'news/facility-demolitions-support-community-reuse-paducah-site', 1, '<p>DOE transferred more than 180,000 pounds of reusable and recyclable materials recovered during the demolition process for 16 unused, outdated facilities at the&nbsp;Paducah Site&nbsp;over the past year to a local community reuse organization.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (628, 'article', 'Paducah Site Recruits Future Interns at STEM Career Fair', 'news/paducah-site-recruits-future-interns-stem-career-fair', 1, '<p>Cleanup contractors at&nbsp;DOE’s&nbsp;Paducah Site&nbsp;engaged with the next-generation workforce at a Murray State University career fair for students from the science, technology, engineering, mathematics (STEM) and occupational safety and health (OSH) fields.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (629, 'article', 'Contractors Share Paducah Site Job Opportunities With Over 800 Students', 'news/contractors-share-paducah-site-job-opportunities-over-800-students', 1, '<p>Contractors at&nbsp;DOE’s&nbsp;Paducah Site&nbsp;recently teamed up to highlight career opportunities available at the site during the Paducah Area Chamber of Commerce WKY (West Kentucky) Launch Experience. The DOE representatives gave hands-on presentations about jobs ranging from engineering and science to the production of documents to over 800 middle school students from across the region. “Events allowing us to showcase the career opportunities at the site casts an early recruiting net in a student’s academic career,”&nbsp;Portsmouth/Paducah Project Office&nbsp;(PPPO) Manager Joel Bradburne said. “PPPO and our contractors are committed to outreach efforts with local schools hoping to cultivate tomorrow’s talent.”&nbsp;Paducah Site&nbsp;contractors Four Rivers Nuclear Partnership (FRNP), Swift &amp; Staley Inc. and Mid-America Conversion Services, along with United Steel Workers Local 550, participated in the event. In this photo, FRNP Data Analyst Emily Coriell, right, demonstrates a pipe crawling robot at the event.</p>', 'filtered_html', '2163', '{"pr_photo":"15959","source":"https://www.energy.gov/em/articles/contractors-share-paducah-site-job-opportunities-over-800-students"}', 1, 'published', NULL, NULL, NULL, '2023-11-14 13:17:25', '2024-01-02 13:27:56') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (630, 'article', 'Paducah Site Showcases Careers at STEM 4 Girls Event', 'news/paducah-site-showcases-careers-stem-4-girls-event', 1, '<p>As women account for about half of U.S. workers in the fields of math and physical science,&nbsp;DOE’s&nbsp;Paducah Site&nbsp;continues to ensure young girls are exposed to opportunities in such STEM fields.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (631, 'article', 'Pipe Crawling Robot Helps Paducah Prepare for Demolition', 'news/pipe-crawling-robot-helps-paducah-prepare-demolition', 1, '<p>Identifying which sections of piping to be removed from the&nbsp;C-333 Process Building&nbsp;at&nbsp;DOE’s&nbsp;Paducah Site&nbsp;can be like trying to find a needle in a haystack.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (632, 'article', 'Paducah Removes 1 Million Pounds of Hazardous Refrigerant in 2023', 'news/paducah-removes-1-million-pounds-hazardous-refrigerant-2023', 1, '<p>The Paducah Site recently met an DOE EM 2023 priority ahead of schedule with the safe and successful disposal of over 1 million pounds of R-114 refrigerant, an environmental hazard stored at the site.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (633, 'article', 'Paducah Crews Downsizing Hundreds of Converters to Prepare for Demolition', 'news/paducah-crews-downsizing-hundreds-converters-prepare-demolition', 1, '<p>How do you prepare to demolish a 1-million-square-foot facility?</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (635, 'article', 'New Paducah Facility to Ensure Safe Disposal of Process Building Equipment', 'news/new-paducah-facility-ensure-safe-disposal-process-building-equipment', 1, '<p>EM’s&nbsp;Paducah Site&nbsp;recently celebrated the startup of a first-of-a-kind scanning facility to ensure equipment removal from massive process buildings are properly prepared for safe and compliant disposal.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (648, 'article', 'Paducah Area Students Address ‘Fast Fashion’ at EcoThink Event', 'news/paducah-area-students-address-‘fast-fashion’-ecothink-event', 1, '<p>Local high school students from western Kentucky and southern Illinois put their problem solving skills to the test during the&nbsp;annual EcoThink&nbsp;project, challenging themselves to address environmental and sustainability issues through critical thinking exercises focused on teamwork and engineering concepts.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (649, 'article', 'Converter Downsizing Picks Up Speed as Paducah Prepares for C-333 Demolition', 'news/converter-downsizing-picks-speed-paducah-prepares-c-333-demolition', 1, '<p>A U.S. Department of Energy (DOE)&nbsp;Office of Environmental Management&nbsp;(EM) team at the&nbsp;Paducah Site&nbsp;has met a goal to increase the efficiency of equipment removal and downsizing at the C-333 Process Building by 80% from an initial startup plan.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (650, 'article', 'Workers Bring Down Paducah Site’s Tallest Structure', 'news/workers-bring-down-paducah-site’s-tallest-structure', 1, '<p>A controlled demolition of the high-pressure fire water tower at the U.S. Department of Energy (DOE) Office of Environmental Management Paducah Site last week took mere seconds, but it required months of planning and preparation ahead to ensure the approximately 300-foot water tower was brought down safely to the ground.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (652, 'request_for_proposal', 'D29 - Natural/Ecological Resource', 'procurement/frnp-d29-25047', 1, NULL, 'filtered_html', NULL, '{"amendments":"16001","department_or_project":"2193","description":"<p>Four Rivers Nuclear Partnership, LLC, hereinafter referred to as the Contractor, is soliciting bids to secure natural resource and ecological services to support the Decision 2029 (D29)regulatory decisions being pursued at the DOE Paducah Site. The vendor or supplier, hereinafter referred to as the subcontractor, shall provide all personnel, equipment, supplies, facilities, transportation, tools, materials, supervision, and other items and non-personal services necessary to perform ecological services as defined in this Performance Statement of Work (PSOW)</p>","rfp_docs":"15990","rfp_number":"FRNP-D29-25047"}', 1, 'draft', NULL, NULL, NULL, '2024-07-16 22:28:16', '2024-08-08 21:13:30') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (653, 'request_for_proposal', 'D29 - Cultural Resource/Historic Preservation Support Services', 'procurement/frnp-d29-0025043', 1, NULL, 'filtered_html', NULL, '{"amendments":"15999","department_or_project":"2193","description":"<p>Four Rivers Nuclear Partnership (FRNP), acting under its Prime contract with the Department of Energy (DOE) is issuing a Request for Proposal (RFP) for Decision 2029 \\u2013 Cultural &nbsp;Resource/Historic Preservation Support Services. All RFP documents are attachments within FRNP-D29-0025043 RFP.</p>\\r\\n\\r\\n<p>All questions must be submitted in writing by 23-Jul-2024, no later than 4:00 p.m. CST. Technical questions shall be directed to Chris Dallas, <a href=\\"mailto:chris.dallas@pad.pppo.gov\\">chris.dallas@pad.pppo.gov</a> and Lee Chandler, <a href=\\"mailto:lee.chandler@pad.pppo.gov\\">lee.chandler@pad.pppo.gov</a> ; cc <a href=\\"mailto:Kelly.layfield@pad.pppo.gov\\">Kelly.layfield@pad.pppo.gov</a></p>\\r\\n\\r\\n<p>All technical and cost proposals are due no later than 26-Jul-2024, no later than 2:00 p.m. CST. Proposals shall be emailed to the Subcontractor Administrator, Kelly Layfield</p>","rfp_docs":"15995","rfp_number":"FRNP-D29-0025043"}', 1, 'draft', NULL, NULL, NULL, '2024-07-16 22:58:58', '2024-08-19 13:42:17') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
