INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (655, 'request_for_proposal', 'Decision 29 RI/FS Support Services', 'procurement/frnp-d29-0025087', 1, NULL, 'filtered_html', NULL, '{"amendments":"16003","department_or_project":"2193","description":"<p>Four Rivers Nuclear Partnership, LLC (FRNP) is soliciting bids to secure technical resources to support the Decision 2029 (D29) regulatory decisions being pursued at the DOE Paducah Site. The vendor shall provide all personnel, equipment, supplies, facilities, transportation, tools, materials, supervision, and other items and non-personal services necessary to perform Remedial Investigation/Feasibility Studies (RI/FS) Support services.</p>\\r\\n\\r\\n<p>All questions should be sent via email by COB 07/24/2024</p>\\r\\n\\r\\n<p>All technical and cost proposals are due on or before 07/31/2024</p>\\r\\n\\r\\n<p>All questions and proposals shall be addressed to <a href=\\"mailto:john.snyder@pad.pppo.gov\\">john.snyder@pad.pppo.gov</a> &nbsp;</p>","rfp_docs":"15994","rfp_number":"FRNP-D29-0025087"}', 1, 'draft', NULL, NULL, NULL, '2024-07-18 14:41:44', '2024-08-08 21:13:30') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (656, 'request_for_proposal', 'C-400 Complex Remedial Investigation Addendum Drilling Program', 'procurement/frnp-es-0025073', 1, NULL, 'filtered_html', NULL, '{"amendments":"16004","department_or_project":"2206","description":"<p>Four Rivers Nuclear Partnership is soliciting drilling services to support the C-400 Complex Remedial Investigation Addendum Drilling Program at the Paducah Gaseous Diffusion Plant in Kevil, KY.&nbsp;</p>\\r\\n\\r\\n<p>All questions should be sent via email by COB 08/05/2024</p>\\r\\n\\r\\n<p>All technical and cost proposals are due on or before 08/08/2024</p>\\r\\n\\r\\n<p>All questions and proposals shall be addressed to <a href=\\"mailto:john.snyder@pad.pppo.gov\\">john.snyder@pad.pppo.gov</a> &nbsp;</p>","rfp_docs":"16002","rfp_number":"FRNP-ES-0025073"}', 1, 'draft', NULL, NULL, NULL, '2024-07-25 22:05:43', '2024-09-06 15:23:01') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (657, 'request_for_proposal', 'OSWDF Design Engineering Support Services', 'procurement/frnp-d29-0025316', 1, NULL, 'filtered_html', NULL, '{"amendments":"16010","department_or_project":"2193","description":"<p>Four Rivers Nuclear Partnership (FRNP) is soliciting engineering services to provide design, engineering studies, engineering support, and project integration in support of construction of a potential On-Site Waste Disposal Facility (OSWDF) at the U.S. Department of Energy\\u2019s (DOE) Paducah Gaseous Diffusion Plant (PGDP) site near Paducah, Kentucky. &nbsp;Please review the solicitation carefully and provide proposals in two volumes \\u2013 Volume 1-Technical and Volume 2-Cost/Contractual on or before 8/29/2024@ 2:00 pm CST.&nbsp; Sections L and M provide instruction on what is needed to be provided at a minimum in the proposal.</p>\\r\\n\\r\\n<p>Below is a solicitation schedule for this procurement:</p>\\r\\n\\r\\n<ul>\\r\\n\\t<li>Pre-Proposal Teams Meeting - 8/15/2024 at 10:00 am CST (Microsoft Teams meeting notice will be sent to those interested in attending prior to this meeting)</li>\\r\\n\\t<li>Questions submittal \\u2013 COB 8/21/2024</li>\\r\\n\\t<li>Proposal Due \\u2013 8/29/2024 at 2:00 pm CST</li>\\r\\n</ul>","rfp_docs":"16005","rfp_number":"FRNP-D29-0025316"}', 1, 'draft', NULL, NULL, NULL, '2024-08-07 14:02:17', '2025-02-14 18:14:16') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (658, 'request_for_proposal', 'CWWT Design Engineering Support Services', 'procurement/frnp-d29-0025761', 1, NULL, 'filtered_html', NULL, '{"amendments":"16012","department_or_project":"2193","description":"<p>Four Rivers Nuclear Partnership, LLC, (FRNP) is soliciting a contract for design, engineering studies, engineering support, and project integration in support of the construction of two water treatment facilities. The first scope is for an optimization of the interim remedial action of the Northwest plume C-400 Extraction well ground water treatment system. The second long-term site solution scope is for the Centralized Wastewater Treatment Facility (CWWT). Both systems will be constructed at the U.S. Department of Energy\\u2019s (DOE) Paducah Gaseous Diffusion Plant (PGDP) site near Paducah, Kentucky. &nbsp;</p>\\r\\n\\r\\n<p>Please review the Request for Proposal (RFP) carefully and provide proposals in two volumes \\u2013 Volume 1-Technical and Volume 2-Cost/Contractual on or before 10/14/2024 at 2:00 pm CT. Sections L and M provide instruction on what is needed to be provided at a minimum in the proposal.</p>\\r\\n\\r\\n<p>Below is a solicitation schedule for this procurement:</p>\\r\\n\\r\\n<ul>\\r\\n\\t<li>Pre-Proposal Teams Meeting \\u2013 09/24/2024 at 10:00 am CT (Microsoft Teams meeting notice will be sent prior to this meeting)</li>\\r\\n\\t<li>Questions submittal \\u2013 09/30/2024 at 10:00 am CT (All questions must be submitted in writing)</li>\\r\\n\\t<li>Proposal Due \\u2013 10/14/2024 at 2:00 pm CT</li>\\r\\n</ul>","rfp_docs":"16011","rfp_number":"FRNP-D29-0025761"}', 1, 'draft', NULL, NULL, NULL, '2024-09-17 19:07:24', '2025-02-14 18:14:16') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (659, 'article', 'Paducah Tests Drones for Emergency Response', 'news/paducah-tests-drones-emergency-response', 1, '<p>Drones are undergoing testing to support emergency response at the U.S. Department of Energy&nbsp;Office of Environmental Management’s (EM)&nbsp;Paducah Site.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (660, 'article', 'Workshop Boosts Small Business, Resilience of Supply Chain', 'news/workshop-boosts-small-business-resilience-supply-chain', 1, '<p>A U.S. Department of Energy (DOE) center demonstrated its commitment to empowering small businesses at a recent workshop in collaboration with the DOE&nbsp;Office of Environmental Management&nbsp;(EM)&nbsp;Portsmouth/Paducah Project Office&nbsp;(PPPO) and a&nbsp;Paducah Site&nbsp;contractor.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (661, 'article', 'Interns Encounter Unique Experiences', 'news/interns-encounter-unique-experiences', 1, '<p>Internship programs at the U.S. Department of Energy (DOE)&nbsp;Office of Environmental Management’s (EM) Portsmouth, Paducah, and Lexington sites began a new, collaborative effort this summer aimed at enhancing knowledge-sharing and professional development.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (662, 'article', 'FRNP Receives Kentucky Governor’s Safety Award', 'news/frnp-receives-kentucky-governor’s-safety-award', 1, '<p>In a significant recognition of excellence coming from the top level of state government, U.S. Department of Energy&nbsp;Office of Environmental Management&nbsp;(EM)&nbsp;Paducah Site&nbsp;contractors Four Rivers Nuclear Partnership, Swift &amp; Staley and Mid-America Conversion Services have been honored with the 2024 Kentucky Labor Cabinet Governor''s Safety and Health Award for their exceptional performance and commitment to creating a safe work environment.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (663, 'article', 'Video Celebrates Hispanic Heritage Month at Paducah Site', 'news/video-celebrates-hispanic-heritage-month-paducah-site', 1, '<p>The U.S. Department of Energy&nbsp;Office of Environmental Management&nbsp;Paducah Site&nbsp;is marking Hispanic Heritage Month with a special celebration, underscoring the importance of diversity and inclusion in the workplace. This year, the site produced a&nbsp;video&nbsp;shining a light on the rich cultural contributions and career achievements of its Hispanic employees.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (664, 'article', 'Crews Open Paducah Process Building Tanks for First Time in 70 Years', 'news/crews-open-paducah-process-building-tanks-first-time-70-years', 1, '<p>For the first time in 70 years, crews at the U.S. Department of Energy&nbsp;Office of Environmental Management&nbsp;(EM)&nbsp;Paducah Site&nbsp;recently opened storage tanks used in the uranium enrichment process.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (665, 'article', 'Paducah Transfers 765,000 Pounds of Recyclables, Fueling Economic Growth', 'news/paducah-transfers-765000-pounds-recyclables-fueling-economic-growth', 1, '<p>PADUCAH, Ky.&nbsp;— The U.S. Department of Energy&nbsp;Office of Environmental Management’s&nbsp;Paducah Site&nbsp;recently transferred more than 765,000 pounds of equipment and recyclable metal to the Paducah Area Community Reuse Organization (PACRO) for the fiscal year ending Sept. 30, marking a significant opportunity for regional economic growth. The estimate market value of this year’s transfer is nearly $175,000.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (666, 'article', 'Drones Fly the Sky to Improve Surveys of Paducah Site Landfill', 'news/drones-fly-sky-improve-surveys-paducah-site-landfill', 1, '<p>PADUCAH, Ky.&nbsp;— Engineers at the U.S. Department of Energy&nbsp;Office of Environmental Management&nbsp;(EM)&nbsp;Paducah Site&nbsp;are making strides in implementing new technology by using drones to survey the site’s sanitary landfill.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (667, 'request_for_proposal', 'Land Transfer – Cultural Resource / Historic Preservation Support', 'procurement/frnp-ts-0027387', 1, NULL, 'filtered_html', NULL, '{"department_or_project":"2234","description":"<p>To support Cultural surveys for Parcel 1 land transfer project at the DOE Paducah site</p>","rfp_docs":"16041","rfp_number":"FRNP-TS-0027387"}', 1, 'draft', NULL, NULL, NULL, '2025-03-20 12:31:19', '2025-04-14 13:20:39') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (679, 'request_for_proposal', 'Design and Fabrication of PEMB', 'procurement/frnp-rdi-29571', 1, NULL, 'filtered_html', NULL, '{"amendments":"16074","department_or_project":"2193","description":"<p>Four Rivers Nuclear Partnership, LLC (FRNP) is issuing Request for Proposal (RFP) No. FRNP-RDI-29. Please review the RFP package in its entirety. Special attention should be given to all highlighted and/or bolded text, as these sections identify critical requirements and proposal instructions.<br />\\r\\n<br />\\r\\nKey Dates and Milestones:</p>\\r\\n\\r\\n<ul>\\r\\n\\t<li>Pre-Bid Virtual Meeting: January 8, 2026 (Meeting invitations will be issued separately)</li>\\r\\n\\t<li>Deadline for Written Questions: January 14, 2026, no later than 12:00 noon (CST)</li>\\r\\n\\t<li>Proposal Due Date: January 29, 2026, Close of Business (CST)</li>\\r\\n</ul>\\r\\n\\r\\n<p><br />\\r\\nAll technical documents included with the RFP are paper-clipped to the PDF and should be reviewed carefully.<br />\\r\\n<br />\\r\\nVendors are requested to acknowledge receipt of this RFP via return email.<br />\\r\\n<br />\\r\\nShould you have any questions, please submit them in accordance with the instructions and deadlines identified in the RFP.</p>\\r\\n\\r\\n<p><strong>UPDATE:</strong></p>\\r\\n\\r\\n<p>Amendment 001 of FRNP-RDI-29571</p>\\r\\n\\r\\n<p>FRNP is reducing the number of cranes to be procured by one (1). Please see Amendment 001 attached. There are five (5) documents attached to the main PDF using the Adobe Attachments function (paperclip).</p>\\r\\n\\r\\n<p>The deadline for the receipt of written questions and proposals is not being extended.</p>\\r\\n\\r\\n<p>Please email your questions to&nbsp;Amanda.Hatton@pad.pppo.gov&nbsp;by Wednesday, January 14th, 2026, no later than 12:00 noon (CT).</p>\\r\\n\\r\\n<p><strong>UPDATE:</strong></p>\\r\\n\\r\\n<p>Amendment 002 of FRNP-RDI-29571</p>\\r\\n\\r\\n<p>FRNP is releasing the answers to the written questions that were submitted. Please see Amendment 002.</p>\\r\\n\\r\\n<p>The deadline for the receipt of proposals is not being extended. Proposals are due to be received by Thursday, January 29, 2026, Close of Business (CT).</p>\\r\\n\\r\\n<p><strong>UPDATE:&nbsp;</strong></p>\\r\\n\\r\\n<p>Amendment 003 of FRNP-RDI-29571</p>\\r\\n\\r\\n<p>Please see Amendment 003.</p>\\r\\n\\r\\n<p>The deadline for the receipt of proposals is being extended. Proposals are now due to be received by 12:00 (Noon) CT, Thursday, February 05, 2026.</p>\\r\\n\\r\\n<p><strong>UPDATE:</strong></p>\\r\\n\\r\\n<p>Amendment 004 of FRNP-RDI-29571</p>\\r\\n\\r\\n<p>Please see Amendment 004.</p>\\r\\n\\r\\n<p>The deadline for the receipt of proposals is being extended. Proposals are now due to be received by 12:00 (Noon) CT, Tuesday, February 17, 2026.</p>\\r\\n\\r\\n<p>There are four (4) documents attached to the main PDF using the Adobe Attachments function (paperclip).</p>","rfp_docs":"16052","rfp_number":"FRNP-RDI-29571"}', 1, 'draft', NULL, NULL, NULL, '2026-01-05 13:01:33', '2026-03-31 19:26:45') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (680, 'article', 'Paducah Site Employees Serve as Role Models for Students at Career Event', 'news/paducah-site-employees-serve-role-models-students-career-event', 1, '<p>A study in the International Journal of STEM Education identified the importance of role models encouraging students to see themselves as capable of succeeding in science, technology, engineering and math career fields.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (681, 'article', 'Collaboration With Law Enforcement Further Improves Safety at Paducah Site', 'news/collaboration-law-enforcement-further-improves-safety-paducah-site', 1, '<p>The&nbsp;Paducah Site&nbsp;is continuing its commitment to&nbsp;safety and security&nbsp;by bolstering collaboration with local law enforcement.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (682, 'article', 'Paducah Disposes of 1 Million Pounds of Hazardous Refrigerant', 'news/paducah-disposes-1-million-pounds-hazardous-refrigerant', 1, '<p>The&nbsp;Paducah Site&nbsp;met a U.S. Department of Energy&nbsp;Office of Environmental Management&nbsp;(EM)&nbsp;2024 priority&nbsp;by safely and successfully removing 1 million pounds of R-114 refrigerant — a legacy environmental hazard stored at the site — this year.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (683, 'article', 'Water Tower Demolition Video Wins Prestigious Telly Award for Paducah Site', 'news/water-tower-demolition-video-wins-prestigious-telly-award-paducah-site', 1, '<p>A video featuring last year’s safe and successful&nbsp;demolition of a 300-foot water tower&nbsp;at the&nbsp;Paducah Site&nbsp;was recognized as a Gold Telly Award winner for excellence in video production out of more than 13,000 entries from across the globe.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (684, 'article', 'Paducah Site Completes Key Survey, Advancing Toward First Land Transfer', 'news/paducah-site-completes-key-survey-advancing-toward-first-land-transfer', 1, '<p>Officials are a step closer to the first land transfer at the&nbsp;Paducah Site&nbsp;for future reuse and economic development after completing a comprehensive survey of the 188-acre parcel that identifies environmental impacts through review of records of past operations and inspections, historical photographs, and interviews with former and current employees.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (685, 'article', 'Creative Solutions Help Paducah Site Reach Demolition Milestone', 'news/creative-solutions-help-paducah-site-reach-demolition-milestone', 1, '<p>Crews have safely demolished six unused facilities at the&nbsp;Paducah Site&nbsp;ahead of schedule and under budget in the current fiscal year ending Sept. 30, reducing the cleanup footprint by more than 19,000 square feet and supporting future reuse of land and economic development.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (686, 'article', 'National Safety Council Award Demonstrates Successful Safety Culture', 'news/national-safety-council-award-demonstrates-successful-safety-culture', 1, '<p>The&nbsp;National Safety Council&nbsp;has awarded the deactivation and remediation contractor at the&nbsp;Paducah Site&nbsp;its Million Work Hours Award, reflecting the safe completion of some of the most complex and challenging work at the site.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (687, 'article', 'Novel Amateur Radio Drill Aids in Emergency Communications at Paducah', 'news/novel-amateur-radio-drill-aids-emergency-communications-paducah', 1, '<p>The U.S. Department of Energy (DOE)&nbsp;Office of Environmental Management&nbsp;(EM)&nbsp;Paducah Site&nbsp;has incorporated amateur radio into a drill for its emergency management program — a first in the nuclear cleanup complex that demonstrates the site’s ability to maintain backup communications in the event of widespread equipment failure or telecommunications service loss during an emergency.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (688, 'article', 'Paducah Crews Brings Innovation, Lessons From One Cleanup Project to Next', 'news/paducah-crews-brings-innovation-lessons-one-cleanup-project-next', 1, '<p>Cleanup crews are wrapping up work to prepare the C-333 Process Building for future demolition, and they are taking lessons learned in innovation, efficiency and&nbsp;safety&nbsp;with them as they shift focus to the C-337 Process Building at the U.S. Department of Energy&nbsp;Office of Environmental Management&nbsp;(EM)&nbsp;Paducah Site.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (689, 'article', 'Investigation Yields Critical Data for Paducah Site Cleanup Decisions', 'news/investigation-yields-critical-data-paducah-site-cleanup-decisions', 1, '<p>The U.S. Department of Energy&nbsp;Office of Environmental Management&nbsp;(EM) partnered with a&nbsp;University of Kentucky&nbsp;consortium and research center to complete field work culminating a larger investigation that provides valuable geologic data for upcoming cleanup decisions at the&nbsp;Paducah Site.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (690, 'article', 'Paducah Achieves Goal to Remove 497 Converters From First Process Building', 'news/paducah-achieves-goal-remove-497-converters-first-process-building', 1, '<p>Since work began to prepare the first former uranium enrichment process building for eventual demolition at the&nbsp;Paducah Site, one number loomed large: 497. That’s the total number of large process components, called converters, the team needed to remove from the C-333 Process Building.</p>
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (691, 'article', 'FRNP Putting the "Future in Focus" for Next Phase of Contract', 'news/frnp-putting-future-focus-next-phase-contract', 1, '<p>Four Rivers Nuclear Partnership is executing the next phase of our contract at the U.S. Department of Energy Paducah Site by putting the “Future in Focus”. Our team of proven professionals are prepared to undertake the challenges to prepare the DOE Paducah Site for future reindustrialization through strategic cleanup and demolition of former enrichment facilities while working closely with our stakeholders and the community to ensure the future is bright for our region.</p>', 'filtered_html', '2857', '{"video":"https://www.youtube.com/watch?v=OPAmucRXIsA","video_photo":"16078"}', 1, 'published', NULL, NULL, NULL, '2026-03-05 21:34:07', '2026-03-05 21:37:49') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (703, 'request_for_proposal', 'Engineering Services', 'procurement/rfp-em-31124', 1, NULL, 'filtered_html', NULL, '{"amendments":"16083","department_or_project":"2859","description":"<p>Four Rivers Nuclear Partnership, LLC, hereinafter referred to as the Contractor, is soliciting bids to obtain services related to design, fabrication, and field support for automation and controls of new and existing ground water extraction wells and corresponding instrumentation for the northwest plume. The vendor or supplier, hereinafter referred to as the subcontractor, shall provide all required engineering, equipment, supplies, facilities, transportation, tools, materials, supervision, and other items and non-personal services necessary to perform the activities as defined in this Performance Statement of Work (PSOW). The quality level for this statement of work is QL-4 per QL determination 15-ENG-121 R4, Subcontract Engineering Services.</p>\\r\\n\\r\\n<p>FRNP Amendment 001 -&nbsp;Proposal Due Date Extension&nbsp;</p>\\r\\n\\r\\n<p>FRNP Amendment 002 -&nbsp;Questions, Responses,&nbsp;Additional Docs</p>","rfp_docs":"16081","rfp_number":"RFP-EM-31124"}', 1, 'published', NULL, NULL, NULL, '2026-08-04 19:48:11', '2026-08-20 23:54:49') ON DUPLICATE KEY UPDATE `type` = VALUES(`type`), `title` = VALUES(`title`), `auto_slug` = VALUES(`auto_slug`), `body` = VALUES(`body`), `format` = VALUES(`format`), `keywords` = VALUES(`keywords`), `fields_data` = VALUES(`fields_data`), `status` = VALUES(`status`), `publish_on` = VALUES(`publish_on`), `unpublish_on` = VALUES(`unpublish_on`), `template` = VALUES(`template`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `nodes` (`id`, `type`, `title`, `slug`, `auto_slug`, `body`, `format`, `keywords`, `fields_data`, `uid`, `status`, `publish_on`, `unpublish_on`, `template`, `created_at`, `updated_at`) VALUES (704, 'page', 'How We Do Cleanup', 'how-we-do-cleanup', 1, '<script>
